from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1]
def main():
    rows=json.loads((ROOT/'reports/part-register.json').read_text())
    audit=json.loads((ROOT/'reports/audit-summary.json').read_text())
    structural=json.loads((ROOT/'reports/structural-prototypes.json').read_text())
    gears=json.loads((ROOT/'reports/printed-gear-trials.json').read_text())
    types=sorted({x['target'] for x in rows})
    options='<option value="">All dispositions</option>'+''.join(f'<option value="{html.escape(t)}">{html.escape(t.replace("_"," ").title())}</option>' for t in types)
    body=''.join(f'<tr data-kind="{html.escape(x["target"])}"><td>{x["id"]:03d}</td><td><strong>{html.escape(x["name"])}</strong><small>{html.escape(x["body"])} · Current: {html.escape(x["current_material"])}</small></td><td>{html.escape(x["target"].replace("_"," ").title())}</td><td>{html.escape(x["reason"])}</td><td>{html.escape(x["release_gate"])}</td></tr>' for x in rows)
    cards=''.join('<tr><td>'+html.escape(x['name'])+'</td><td>'+' × '.join(f'{v:.2f}'.rstrip('0').rstrip('.') for v in x.get('print_bounding_size_mm',x.get('dimensions_mm')))+' mm</td><td>STEP/STL test article</td></tr>' for x in structural['parts']+gears['parts'])
    text='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ARX / 6 · Print-first review</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f5f6;color:#182129;font:15px/1.55 system-ui,-apple-system,sans-serif}main{max-width:1440px;margin:auto;padding:44px 28px 80px}header{border-bottom:1px solid #bfc9cd;padding-bottom:25px}.eyebrow{letter-spacing:.14em;font-size:12px;font-weight:650;color:#46616c}h1{font-size:44px;line-height:1.08;margin:18px 0}h2{font-size:23px;margin-top:34px}p{max-width:1000px}strong{font-weight:650}.notice{background:#fff5dd;border:1px solid #ead39a;padding:14px 18px;margin:22px 0}.scope{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:26px 0}.card{background:white;border:1px solid #d3dcdf;padding:20px}.card b{display:block;font-size:28px;margin-bottom:6px}.controls{display:flex;gap:12px;margin:20px 0;flex-wrap:wrap}input,select{font:inherit;padding:11px 13px;border:1px solid #aebfc5;border-radius:4px;background:white}input{flex:1;min-width:240px}.scroll{overflow:auto;background:white;border:1px solid #d3dcdf}table{border-collapse:collapse;width:100%;font-size:13px}th{padding:13px 12px;text-align:left;background:#223c48;color:white;font-weight:550}td{padding:12px;border-bottom:1px solid #e3e8ea;vertical-align:top}small{display:block;color:#5e717a;margin-top:4px}#register{min-width:1000px}#register td:nth-child(2){width:24%}#register td:nth-child(3){width:17%}#register td:nth-child(4){width:24%}#count{color:#50646d}code{background:#e7edef;padding:2px 4px}@media(max-width:650px){main{padding:24px 16px}.scope{grid-template-columns:1fr}h1{font-size:34px}}
</style><main><header><div class="eyebrow">ARX / 6 · P6-B · ENGINEERING CHECKPOINT</div><h1>Print the structure.</h1><p>Print-first manufacturing, not an aluminum skeleton with transparent covers. Structural links, load-carrying housings and transmission redesigns are in scope. Small functional metal/electromagnetic components are explicit exceptions.</p></header>
<div class="scope"><div class="card"><b>398</b>Existing P6-A component records audited</div><div class="card"><b>136</b>Records in printing or print-oriented redesign scope</div><div class="card"><b>6</b>New geometric test articles supplied</div></div>
<div class="notice"><strong>Target does not mean completed or qualified.</strong> This package contains the full inventory disposition and the first link/gear test pieces. It is not a full printed-robot assembly, powered-operation release, or replacement for the earlier engineering model.</div>
<h2>What is built in this checkpoint</h2><p>The upper/forearm tube spans are reinforced from 2.5 to 6 mm nominal wall. The long upper frame becomes two pieces plus an 80 mm lap coupler with through-sleeve bolt passages. Coarser module-1.2 gripper pinion/rack trials replace the assumption that the original module-0.3 teeth can simply be printed.</p><div class="scroll"><table><thead><tr><th>Test article</th><th>Bounding dimensions</th><th>Status</th></tr></thead><tbody>CARDS</tbody></table></div>
<p>The larger trial pinion needs four times the output torque for the same ideal rack force. It is not integrated with the current jaw mechanism. The source report retains that consequence rather than claiming unchanged gripping performance.</p>
<h2>Checks and boundaries</h2><p>Six watertight, consistently wound, positive-volume single-component STL files; six valid single-solid STEP reimports; nominal three-piece upper-splice interference checked. The structural study is a 36-case uniform-beam surrogate, not complete CAD FEM or actual TCP-error prediction. Full-arm integration, joint compliance, print qualification, creep, thermal behavior and motor/reduction sizing remain open.</p>
<h2>Part-by-part manufacturing disposition</h2><p>The original material is not treated as a reason to keep a whole custom part in metal. Printed carriers may retain small metal journals, preload sleeves, heat-transfer plates or inserts. Purchased reducer envelopes are flagged for a true printed transmission redesign, not relabeled as printable gear internals.</p><div class="controls"><input id="query" placeholder="Search name, body, function or qualification gate" aria-label="Search parts"><select id="kind" aria-label="Filter disposition">OPTIONS</select></div><p id="count">398 records shown</p><div class="scroll"><table id="register"><thead><tr><th>ID</th><th>Component</th><th>Target</th><th>Reason</th><th>Engineering gate</th></tr></thead><tbody>BODY</tbody></table></div><p><small>Canonical sources and executable checks are bundled in the project ZIP. Original P5/P6-A files remain unchanged. No image-generation output is used.</small></p></main><script>
const q=document.getElementById('query'),k=document.getElementById('kind'),rs=[...document.querySelectorAll('#register tbody tr')];function filter(){let n=0;const text=q.value.toLowerCase().trim();for(const r of rs){const yes=(!k.value||r.dataset.kind===k.value)&&(!text||r.textContent.toLowerCase().includes(text));r.hidden=!yes;if(yes)n++;}document.getElementById('count').textContent=n+' of '+rs.length+' records shown';}q.addEventListener('input',filter);k.addEventListener('change',filter);</script></html>'''
    text=text.replace('CARDS',cards).replace('OPTIONS',options).replace('BODY',body)
    (ROOT/'ARX6-P6B-PrintFirst-Review.html').write_text(text)
    print('review written',len(text))
if __name__=='__main__':main()
